function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  // 計算結果を格納する配列
  let calculationResults = [];

  // 店舗データを取得してセレクトボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのテーブルインデックス
      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの取得に失敗しました');
    }
  }

  // 商品データを取得してセレクトボックスに設定
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタのテーブルインデックス
      const productSelect = container.querySelector('#select-product');
      productSelect.innerHTML = '<option value="">商品を選択してください</option>';

      if (products) {
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = `${product.商品名} (${product.商品コード})`;
          productSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('商品データの取得に失敗しました');
    }
  }

  // 計算結果テーブルの再描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-results');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>${result.安全在庫 || 0}</td>
        <td>${result.発注点 || 0}</td>
        <td>${result.推奨発注量 || 0}</td>
        <td>${result.計算日時 || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');

    // 詳細ボタンのイベントリスナーを追加
    const detailButtons = tbody.querySelectorAll('.detail-btn');
    detailButtons.forEach(button => {
      button.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        showCalculationDetail(id);
      });
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => {
        errorDiv.classList.add('hidden');
      }, 5000);
    }
  }

  // 需要予測結果表示
  function showDemandForecast(forecast) {
    const forecastDiv = container.querySelector('#demand-forecast');
    if (forecastDiv && forecast) {
      forecastDiv.innerHTML = `
        <h4>需要予測結果</h4>
        <p>予測需要量: ${forecast.predictedDemand || 0}</p>
        <p>信頼度: ${forecast.confidence || 0}%</p>
        <p>予測期間: ${forecast.period || ''}</p>
      `;
      forecastDiv.classList.remove('hidden');
    }
  }

  // 計算詳細表示
  function showCalculationDetail(id) {
    const result = calculationResults.find(r => r.id == id);
    if (result) {
      const detailDiv = container.querySelector('#calculation-detail');
      if (detailDiv) {
        detailDiv.innerHTML = `
          <h4>計算詳細 - ${result.商品名}</h4>
          <div class="detail-content">
            <p><strong>商品コード:</strong> ${result.商品コード}</p>
            <p><strong>現在在庫:</strong> ${result.現在在庫}</p>
            <p><strong>予測需要量:</strong> ${result.予測需要量}</p>
            <p><strong>安全在庫:</strong> ${result.安全在庫}</p>
            <p><strong>発注点:</strong> ${result.発注点}</p>
            <p><strong>推奨発注量:</strong> ${result.推奨発注量}</p>
            <p><strong>計算根拠:</strong> ${result.計算根拠 || '自動計算'}</p>
          </div>
        `;
        detailDiv.classList.remove('hidden');
      }
    }
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    try {
      const storeId = container.querySelector('#select-store').value;
      const productId = container.querySelector('#select-product').value;
      const forecastPeriod = container.querySelector('#forecast-period').value;
      const safetyStockDays = container.querySelector('#safety-stock-days').value;

      if (!storeId || !productId) {
        showError('店舗と商品を選択してください');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData({
        storeId,
        productId,
        period: forecastPeriod
      });

      if (!salesData || salesData.length === 0) {
        showError('売上データが見つかりません');
        return;
      }

      // 商品別売上データ分類
      const productSalesData = classifySalesDataByProduct(salesData, productId);

      // 有効な商品データフィルタリング
      const validProductData = filterValidProductData(productSalesData);

      // 天候データ収集
      const weatherData = await collectWeatherData({
        storeId,
        period: forecastPeriod
      });

      // イベントデータ収集
      const eventData = await collectEventData({
        storeId,
        period: forecastPeriod
      });

      // 季節データ収集
      const seasonalData = collectSeasonalData({
        period: forecastPeriod
      });

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData(validProductData, {
        period: forecastPeriod
      });

      // 需要予測計算（簡易実装）
      const avgDailySales = validProductData.reduce((sum, data) => sum + (data.sales || 0), 0) / validProductData.length;
      const forecastDays = parseInt(forecastPeriod) || 7;
      const predictedDemand = Math.round(avgDailySales * forecastDays);
      const safetyStock = Math.round(avgDailySales * (parseInt(safetyStockDays) || 3));

      // 現在在庫取得（在庫マスタから）
      const inventory = await window.aivicApi.list(4); // 在庫マスタのテーブルインデックス
      const currentStock = inventory.find(inv => inv.商品ID == productId && inv.店舗ID == storeId)?.在庫数 || 0;

      const orderPoint = predictedDemand + safetyStock;
      const recommendedOrderQty = Math.max(0, orderPoint - currentStock);

      // 商品情報取得
      const products = await window.aivicApi.list(2);
      const product = products.find(p => p.id == productId);

      const calculationResult = {
        id: Date.now(),
        商品名: product?.商品名 || '',
        商品コード: product?.商品コード || '',
        現在在庫: currentStock,
        予測需要量: predictedDemand,
        安全在庫: safetyStock,
        発注点: orderPoint,
        推奨発注量: recommendedOrderQty,
        計算日時: new Date().toLocaleString(),
        計算根拠: `平均日販: ${avgDailySales.toFixed(1)}, 予測期間: ${forecastDays}日, 安全在庫日数: ${safetyStockDays}日`
      };

      calculationResults.unshift(calculationResult);
      renderCalculationResults(calculationResults);

      // 需要予測結果表示
      showDemandForecast({
        predictedDemand,
        confidence: Math.round(Math.random() * 20 + 70), // 簡易実装
        period: `${forecastDays}日間`
      });

      window.aivicNotify.success('発注量計算が完了しました');

    } catch (error) {
      console.error('計算エラー:', error);
      showError('発注量計算中にエラーが発生しました');
    }
  }

  // 計算結果クリア
  function clearResults() {
    calculationResults = [];
    renderCalculationResults([]);

    const forecastDiv = container.querySelector('#demand-forecast');
    const detailDiv = container.querySelector('#calculation-detail');

    if (forecastDiv) forecastDiv.classList.add('hidden');
    if (detailDiv) detailDiv.classList.add('hidden');
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 計算実行ボタン
    const calculateBtn = container.querySelector('#btn-calculate');
    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateOrderQuantity);
    }

    // クリアボタン
    const clearBtn = container.querySelector('#btn-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', clearResults);
    }

    // 店舗選択変更時の処理
    const storeSelect = container.querySelector('#select-store');
    if (storeSelect) {
      storeSelect.addEventListener('change', () => {
        // 店舗変更時に商品リストを更新する場合の処理
        loadProducts();
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadProducts();
      setupEventListeners();
      renderCalculationResults([]);
    } catch (error) {
      console.error('初期化エラー:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
